// Fuentes independientes publicadas para completar las plantillas 2026/27.
// Estos datos NO están certificados por las ligas o clubes oficiales.
// Nombres, posiciones y edades proceden de la fuente citada; salarios, valor,
// cláusulas y duración contractual siguen siendo estimaciones del simulador.
// El tercer campo es la edad observada en noviembre de 2026.
function decodePublishedRoster(rows) {
  return rows.split('\n').filter(Boolean).map((row) => {
    const [name, position, age] = row.split('|');
    return { name, position, ...(age ? { age: Number(age) } : {}) };
  });
}

// Para VI y BallValue el tercer dato es un dorsal, no una edad.
function decodeShirtRoster(rows) {
  return rows.split('\n').filter(Boolean).map((row) => {
    const [name, position, shirt] = row.split('|');
    return { name, position, ...(shirt ? { shirtNumber: Number(shirt) } : {}) };
  });
}

const decodeDutchRoster = decodeShirtRoster;

